-- ============================================================================
-- ISO 3166-1 Country List (Official International Standard)
-- Reference: ISO 3166-1 (Alpha-2, Alpha-3, Numeric-3, Country Names)
-- Total Entries: 249 officially assigned country codes
-- Encoding: UTF-8
-- ============================================================================

-- Oracle Database DDL
CREATE TABLE COUNTRY (
  CD_ISO       VARCHAR2(2)  NOT NULL PRIMARY KEY,
  NM_COUNTRY   VARCHAR2(80) NOT NULL,
  NM_PRINTABLE VARCHAR2(80) NOT NULL,
  CD_ISO3      VARCHAR2(3)  NOT NULL,
  CD_COUNTRY   CHAR(3)      NOT NULL
);

-- ANSI SQL / PostgreSQL / MySQL / SQL Server / SQLite DDL
CREATE TABLE IF NOT EXISTS COUNTRY (
  CD_ISO       CHAR(2)      NOT NULL PRIMARY KEY,
  NM_COUNTRY   VARCHAR(80)  NOT NULL,
  NM_PRINTABLE VARCHAR(80)  NOT NULL,
  CD_ISO3      CHAR(3)      NOT NULL,
  CD_COUNTRY   CHAR(3)      NOT NULL
);

